package service_test

import (
	"context"
	"testing"

	"github.com/flyfleet/fleet-core-service/internal/domains/compliance_v2/service"
	pb "github.com/flyfleet/proto/compliance/v1"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/fleet-platform/shared/pkg/logger"
	"go.uber.org/zap/zapcore"
)

// MockRepository is an autogenerated mock type for the ComplianceRepository type
// Usually generated via `mockgen`, but handcrafted here for the test demonstration
type MockRepository struct {
	mock.Mock
}

func (m *MockRepository) RecordDutyStatus(ctx context.Context, log *pb.DutyStatusLog) error {
	args := m.Called(ctx, log)
	return args.Error(0)
}

func (m *MockRepository) GetLatestDutyStatus(ctx context.Context, driverID string) (*pb.DutyStatusLog, error) {
	args := m.Called(ctx, driverID)
	if args.Get(0) == nil {
		return nil, args.Error(1)
	}
	return args.Get(0).(*pb.DutyStatusLog), args.Error(1)
}

func TestRecordDutyStatus_ValidTransition(t *testing.T) {
	dummyLogger, _ := logger.New(logger.Config{Level: zapcore.InfoLevel})
	mockRepo := new(MockRepository)
	svc := service.NewComplianceService(dummyLogger, mockRepo)

	ctx := context.Background()
	driverID := "driver-123"

	// Mock existing state: Currently OFF_DUTY
	mockRepo.On("GetLatestDutyStatus", ctx, driverID).Return(&pb.DutyStatusLog{
		DriverId: driverID,
		Status:   pb.DutyStatus_OFF_DUTY,
	}, nil)

	// Mock DB save success
	mockRepo.On("RecordDutyStatus", ctx, mock.AnythingOfType("*compliancev1.DutyStatusLog")).Return(nil)

	// Action: Transition to ON_DUTY_NOT_DRIVING
	req := &pb.RecordDutyStatusRequest{
		DriverId: driverID,
		VehicleId: "veh-456",
		Status:   pb.DutyStatus_ON_DUTY_NOT_DRIVING,
	}

	resp, err := svc.RecordDutyStatus(ctx, req)

	// Assert
	assert.NoError(t, err)
	assert.NotNil(t, resp)
	assert.NotNil(t, resp.Log)
	assert.Equal(t, pb.DutyStatus_ON_DUTY_NOT_DRIVING, resp.Log.Status)
	assert.Equal(t, driverID, resp.Log.DriverId)
	
	mockRepo.AssertExpectations(t)
}

func TestRecordDutyStatus_InvalidTransition(t *testing.T) {
	dummyLogger, _ := logger.New(logger.Config{Level: zapcore.InfoLevel})
	mockRepo := new(MockRepository)
	svc := service.NewComplianceService(dummyLogger, mockRepo)

	ctx := context.Background()
	driverID := "driver-invalid"

	// Mock existing state: Currently DRIVING
	mockRepo.On("GetLatestDutyStatus", ctx, driverID).Return(&pb.DutyStatusLog{
		DriverId: driverID,
		Status:   pb.DutyStatus_DRIVING,
	}, nil)

	// Action: Transition directly to YARD_MOVES (should be illegal without ON_DUTY first)
	req := &pb.RecordDutyStatusRequest{
		DriverId: driverID,
		Status:   pb.DutyStatus_YARD_MOVES,
	}

	resp, err := svc.RecordDutyStatus(ctx, req)

	// Assert
	assert.ErrorIs(t, err, service.ErrInvalidTransition)
	assert.Nil(t, resp)
	
	mockRepo.AssertExpectations(t)
}

func TestGetCurrentDutyStatus_NewDriver(t *testing.T) {
	dummyLogger, _ := logger.New(logger.Config{Level: zapcore.InfoLevel})
	mockRepo := new(MockRepository)
	svc := service.NewComplianceService(dummyLogger, mockRepo)

	ctx := context.Background()
	driverID := "driver-new"

	// Mock DB returning nothing (new driver)
	mockRepo.On("GetLatestDutyStatus", ctx, driverID).Return((*pb.DutyStatusLog)(nil), nil)

	resp, err := svc.GetCurrentDutyStatus(ctx, driverID)

	assert.NoError(t, err)
	assert.NotNil(t, resp)
	assert.Equal(t, pb.DutyStatus_OFF_DUTY, resp.Status) // Defaults to OFF_DUTY
	
	mockRepo.AssertExpectations(t)
}
